package com.vetlink.emergencia.controller;
import com.vetlink.emergencia.dto.EmergenciaForm; import com.vetlink.emergencia.model.*; import com.vetlink.emergencia.repository.EmergenciaRepository; import com.vetlink.mascota.repository.MascotaRepository; import com.vetlink.security.VetlinkUserPrincipal; import com.vetlink.usuario.controller.DashboardController; import com.vetlink.usuario.repository.UsuarioRepository; import com.vetlink.veterinaria.repository.VeterinariaRepository; import jakarta.validation.Valid; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.validation.BindingResult; import org.springframework.web.bind.annotation.*; import java.time.LocalDateTime;
@Controller @RequestMapping("/emergencias") public class EmergenciaController {
 private final EmergenciaRepository repo; private final MascotaRepository mascotas; private final VeterinariaRepository veterinarias; private final UsuarioRepository usuarios;
 public EmergenciaController(EmergenciaRepository repo,MascotaRepository mascotas,VeterinariaRepository veterinarias,UsuarioRepository usuarios){this.repo=repo;this.mascotas=mascotas;this.veterinarias=veterinarias;this.usuarios=usuarios;}
 @GetMapping public String listar(@AuthenticationPrincipal VetlinkUserPrincipal p,Model m){shell(m,p);var u=p.getUsuario();switch(u.getRol()){case TUTOR->{m.addAttribute("emergencias",repo.findByMascota_Tutor_IdUsuarioOrderByCreadaEnDesc(u.getIdUsuario()));m.addAttribute("mascotas",mascotas.findByTutor_IdUsuarioAndEstado(u.getIdUsuario(),(byte)1));m.addAttribute("veterinarias",veterinarias.findByEstado((byte)1));m.addAttribute("form",new EmergenciaForm());}case VETERINARIO->m.addAttribute("emergencias",repo.findByVeterinario_IdUsuarioOrderByCreadaEnDesc(u.getIdUsuario()));case RECEPCIONISTA->{var v=u.getRecepcionista().getVeterinaria();m.addAttribute("emergencias",repo.findByVeterinaria_IdVeterinariaOrderByCreadaEnDesc(v.getIdVeterinaria()));m.addAttribute("veterinarios",usuarios.findAll().stream().filter(x->x.getVeterinario()!=null&&x.getVeterinario().getVeterinaria().getIdVeterinaria().equals(v.getIdVeterinaria())).toList());} }return "emergencias/lista";}
 @PostMapping public String crear(@AuthenticationPrincipal VetlinkUserPrincipal p,@Valid @ModelAttribute("form") EmergenciaForm f,BindingResult r,Model m){if(r.hasErrors())return listar(p,m);var mascota=mascotas.findById(f.getIdMascota()).orElseThrow();if(!mascota.getTutor().getIdUsuario().equals(p.getUsuario().getIdUsuario()))throw new org.springframework.security.access.AccessDeniedException("La mascota no te pertenece"); Emergencia e=new Emergencia();e.setMascota(mascota);e.setVeterinaria(veterinarias.findById(f.getIdVeterinaria()).orElseThrow());e.setMotivo(f.getMotivo().trim());e.setDetalle(f.getDetalle());e.setCreadaEn(LocalDateTime.now());repo.save(e);return "redirect:/emergencias?creada";}
 @PostMapping("/{id}/asignar") public String asignar(@PathVariable Integer id,@RequestParam Integer idVeterinario,@AuthenticationPrincipal VetlinkUserPrincipal p){Emergencia e=deMiClinica(id,p);var v=usuarios.findById(idVeterinario).orElseThrow();if(v.getVeterinario()==null||!v.getVeterinario().getVeterinaria().getIdVeterinaria().equals(e.getVeterinaria().getIdVeterinaria()))throw new org.springframework.security.access.AccessDeniedException("Veterinario inválido");e.setVeterinario(v);e.setEstado(EstadoEmergencia.ASIGNADA);repo.save(e);return "redirect:/emergencias?asignada";}
 @PostMapping("/{id}/estado") public String estado(@PathVariable Integer id,@RequestParam EstadoEmergencia estado,@AuthenticationPrincipal VetlinkUserPrincipal p){Emergencia e=repo.findById(id).orElseThrow();if(p.getUsuario().getRol()==com.vetlink.usuario.model.Rol.VETERINARIO&& (e.getVeterinario()==null||!e.getVeterinario().getIdUsuario().equals(p.getUsuario().getIdUsuario())))throw new org.springframework.security.access.AccessDeniedException("No tienes asignada esta emergencia");if(p.getUsuario().getRol()==com.vetlink.usuario.model.Rol.RECEPCIONISTA)deMiClinica(id,p);e.setEstado(estado);repo.save(e);return "redirect:/emergencias?actualizada";}
 private Emergencia deMiClinica(Integer id,VetlinkUserPrincipal p){Emergencia e=repo.findById(id).orElseThrow();if(p.getUsuario().getRecepcionista()==null||!e.getVeterinaria().getIdVeterinaria().equals(p.getUsuario().getRecepcionista().getVeterinaria().getIdVeterinaria()))throw new org.springframework.security.access.AccessDeniedException("No pertenece a tu veterinaria");return e;}
 private void shell(Model m,VetlinkUserPrincipal p){m.addAttribute("usuario",p.getUsuario());m.addAttribute("seccionActiva","emergencias");m.addAttribute("navItems",switch(p.getUsuario().getRol()){case TUTOR->DashboardController.navTutor();case VETERINARIO->DashboardController.navVeterinario();case RECEPCIONISTA->DashboardController.navRecepcionista();});}
}
